files.store.js:
const users = new Map([["1", { id: "1", name: "Ada" }]])
function getUser(id) { return users.get(id) }
function updateUser(id, patch) { users.set(id, { ...users.get(id), ...patch }) }
module.exports = { getUser, updateUser }

files.cache.js:
const { getUser } = require('./store')
const cache = new Map()
function findUser(id) { if (!cache.has(id)) cache.set(id, getUser(id)); return cache.get(id) }
module.exports = { findUser }

files.test.js:
const assert = require('assert')
const { updateUser } = require('./store')
const { findUser } = require('./cache')
assert.strictEqual(findUser('1').name, 'Ada')
updateUser('1', { name: 'Grace' })
assert.strictEqual(findUser('1').name, 'Grace')
console.log('ok')

